CREATE TABLE operational_requests(restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES users(id),operation_key text NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(restaurant_id,branch_id,user_id,operation_key),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
